play_sound:
E233: 8E E3 D5        LDX    #sound_voice    ; first voice of this sound
E236: D6 C0           LDB    <snd_current    ; [$00C0]
E238: A6 85           LDA    B,X
E23A: 97 C1           STA    <snd_voice      ; [$00C1]
E23C: 8E E4 09        LDX    #sound_channels ; its channel blocks
E23F: 58              ASLB
E240: AE 85           LDX    B,X
E242: CE 00 60        LDU    #snd_active     ; first frame of this sound?
                                             ; [#$0060]
E245: 54              LSRB
E246: A6 C5           LDA    B,U
E248: 26 35           BNE    play_voice
E24A: 6C C5           INC    B,U
E24C: CE E4 3D        LDU    #sound_headers  ; header -> channel blocks
E24F: 58              ASLB
